mapper.update:
UPDATE identity.password_reset_token
   SET invalidated_at = #{at}
 WHERE user_id = #{userId}
   AND used_at IS NULL
   AND invalidated_at IS NULL

mapper.select:
SELECT id, request_id, user_id, token_hash, issued_at, expires_at, used_at, invalidated_at
  FROM identity.password_reset_token
 WHERE id = #{id}

mapper.update:
UPDATE identity.password_reset_token
   SET used_at = #{at}
 WHERE id = #{id}
   AND used_at IS NULL
   AND invalidated_at IS NULL
   AND expires_at > #{at}

mapper.select:
SELECT id, request_id, user_id, token_hash, issued_at, expires_at, used_at, invalidated_at
  FROM identity.password_reset_token
 WHERE token_hash = #{tokenHash}
